encryptedMessage = ""

# Function to calculate key length.
# More specifically calculates the length of the key used in the Vigenere cipher.
# It iterates through possible key lengths and calculates the sum of probabilities
# for each letter within the English alphabet. If the sum falls within a certain
# range, the key length is determined.
def keyLengthCalc(cipher):
    # Initialize variables
    keyFound = False
    keyLength = 0

    # Loop through all possible lengths(1 to legnth of cipherText)
    for parseKey in range(1, len(cipher)):
        sum = 0

        # Calculate the sum of probabilities for each letter, within English alphabet
        for chr in ascii_uppercase:
            sub_cipher = cipher[::parseKey]

            # Call letter_frequency function
            frequency = frequencyCalc(sub_cipher, chr)

            # Call key_probability function
            prob = probabilityCalc(sub_cipher, frequency)

            # Calculate the sum
            sum = sum + prob

        # Check if the sum falls within the certain range
        if not keyFound and lowerFreq <= sum <= upperFreq:
            keyFound = True
            keyLength = parseKey

    return keyLength

# Function to calculate the frequency of a letter of the cipher
def frequencyCalc(cipher, chr):
    return Counter(cipher).get(chr)

# Function to calculate the combined frequency
def frequencyCalcEnc(encryptedLettersFrequency,letterFrequency):
    # Initialize variables
    frequencySum = 0

    # Calculate the combined frequency, as frequency of each letter in the text versus english alphabet
    for i in range(26):
        frequencySum = frequencySum + (encryptedLettersFrequency[i]*letterFrequency[i])

    return frequencySum

# Function to calculate the probability of a letter based on its frequency in the cipher
def probabilityCalc(cipher, frequency):
    if frequency is not None:
        return np.square(frequency / len(cipher))
    else:
        return 0

# Function to analyze frequency.
# Performs frequency analysis on the encrypted message. It analyzes the frequency
# of letters in the encrypted message by considering each letter at a specific position
# determined by the key length. It counts the occurrences of each letter and calculates
# the frequency of each letter in the encrypted message.
def analyzeFrequency(encryptedMessage, keyLength):
    # Initialize variables
    keyDigitList = list()
    letterCounterList = [0]*26
    encryptedLettersFrequency = list()
    frequencySumList = list()
    frequencySum = 0

    # Parse all letters in encryptedMessage and add them to a list
    print('Analysing frequency...')
    for f in range(keyLength):
        letterCounterList = [0]*26
        encryptedLettersFrequency = list()
        frequencySumList = list()
        frequencySum = 0
        for i in range(f,len(encryptedMessage),keyLength):
            for j in range(len(englishAlphabet)):
                if(encryptedMessage[i] == englishAlphabet[j]):
                    letterCounterList[j] = letterCounterList[j] + 1
        total = 0

        # Get the total counter, as part of calulating the frequency
        for i in range(26):
            total = total + letterCounterList[i]

        # Calculate frequency
        for i in range(26):
            encryptedLettersFrequency.append(letterCounterList[i]/total)

        # Get the total frequency sum
        for i in range(26):
            frequencySum = frequencySum + (encryptedLettersFrequency[i]*letterFrequency[i])

        # Calculate rotation sums
        for i in range(26):
            frequencySumList.append(frequencyCalcEnc(encryptedLettersFrequency,letterFrequency))
            # Rotate by 1
            encryptedLettersFrequency = encryptedLettersFrequency[1:] + encryptedLettersFrequency[:1]

        maxFreq = 0
        # Identify  max frequency, along with key's position
        for i in range(26):
            if (frequencySumList[i]>maxFreq):
                maxFreq = frequencySumList[i]
                keyDigit = i
        keyDigitList.append(keyDigit)

    print('Key List ', keyDigitList)

    keyListExtended = list(np.resize(keyDigitList,len(encryptedMessage)))
    return keyListExtended

# Calculate keyLength
print('Calculating key length...')
keyLength = keyLengthCalc(encryptedMessage)
print("Key Length: " + str(keyLength))

# The code then uses the calculated key length and the frequency analysis results to decrypt
# the encrypted message. It iterates through each letter of the encrypted message and finds
# the corresponding letter in the English alphabet by subtracting the key digit (determined
# from the frequency analysis) from the encrypted letter.
# The decrypted message is stored in the decryptList variable and is printed as the final output.

# Call function analyzeFrequency to get the extended key list with frequencies
keyListExtended = analyzeFrequency(encryptedMessage, keyLength)

# Decrypt process
decryptList = list()
print('Decryption process...')

for i in range(len(encryptedMessage)):
    for j in range(len(englishAlphabet)):
        # Parse each letter of the encrypted message, check inside the alphabet
        if(encryptedMessage[i] == englishAlphabet[j]):
            message = decryptList.append(englishAlphabet[j-keyListExtended[i]])
print('The original/decrypted message is:',''.join(decryptList))
